
import './App.css';
import { useTranslation } from 'react-i18next';
import { useEffect,useState } from 'react';
import Language from './Language';
import {   Routes,  Route,  useParams} from "react-router-dom"
import { Launchpage } from './maincomponent/Launchpage';
import Theory from './maincomponent/Theory';
import Instruction from './maincomponent/Instruction';
import HelpingTools from './maincomponent/HelpingTools';

import { v4 as uuid } from 'uuid';
import axios from "axios";

import logconfig from './config/dbconfig.js';
import useWebSocket from 'react-use-websocket';
import ReactGA from "react-ga4";
import Level1Old from './maincomponent/Level1Old';
import Level1 from './maincomponent/Level1';
import Level2 from './maincomponent/Level2.js';
import Levels from './maincomponent/Levels';
import L2SelectLetter from './maincomponent/L2SelectLetter';
import Quizmain from './maincomponent/Quizmain';
import Procedure from './maincomponent/Procedure.js';
import Errorpage from './maincomponent/Errorpage.js';
import Animation from './maincomponent/Animation.js';
import CompletedLevel1 from './maincomponent/CompletedLevel1.js';
import CompletedLevel2 from './maincomponent/CompletedLevel2.js';




function App() {
  const { id } = useParams();
  const { t, i18n } = useTranslation();
  const [ip, setIP] = useState("");
  const sid = uuid();

  useEffect(() => {
   
    //alert("in app en : ",id);
       if (id == "en") {
       alert("in app en : ",id);
      i18n.changeLanguage("en");
    }
    if (id == "hn") {
      alert("in app hn : ",id);
      console.log("inside hindi")
      i18n.changeLanguage("hn");
    }

  }, []);

  useEffect(() => {
    ReactGA.initialize("G-ZLKNSX7SDM", {
     gaOptions: {
       gtag: true,
     },
   }
   );
    }, []);

  useEffect(() => {
    localStorage.setItem("sessionid",sid);
  }, []);


  useEffect(()=>{
    // to call get data function which return ip address
    getData()    
  },[ip]);

    //creating function to load ip address from the API
    const getData = async () => {
      // const res = await axios.get('https://api.ipify.org/?format=json')
      try{
          const res = await axios.get('http://10.212.8.133:8083/get_ip')
          //console.log(res.data);
          setIP(res.data.ip)
          localStorage.setItem("clientip",ip);
      }
      catch(error){
      }
    }

    const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
      onOpen: () => {console.log('WebSocket connection established hi.');},
      onError:()=>{console.log('WebSocket connection Error');},
      share: true,
      filter: () => false,
      retryOnError: true,
      shouldReconnect: () => true
    });
  return (
    <div className="App">
      <Routes>
      <Route exact path="/" element={<Launchpage/>}/>
      <Route path="*" element={<Errorpage />} />
      <Route exact path="/letusverify" element={<Launchpage/>}/>
      <Route path="/theory" element={<Theory />} />
      <Route path="/instruction" element={<Instruction />} />
      <Route path="/helpingtools" element={<HelpingTools />} />
      <Route path="/levels" element={<Levels />} />
      <Route path="/l2-select-letter" element={<L2SelectLetter />} />
      <Route path="/level1" element={<Level1/>} />
      <Route path="/level2" element={<Level2/>} />
      <Route path="/quiz" element={<Quizmain />}/>
      <Route path="/procedure" element={<Procedure/>}/>
      <Route path="/animation" element={<Animation/>}/>
      <Route path="/completedLevel1" element={<CompletedLevel1/>}/>
      <Route path="/completedLevel2" element={<CompletedLevel2/>}/>

      </Routes>

    </div>
  );
}

export default App;
