import React, { useState,useEffect } from "react";
import { Button } from "@mui/material";
import { Dropdown } from "react-bootstrap";
import {Dialog,Tooltip} from '@mui/material';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import DialogContentText from '@mui/material/DialogContentText';
import SecondLevelLetter from "../resources/SecondLevelLetter.json";
import i_image from "../Img/info.png";
import { useNavigate } from "react-router-dom";
import logconfig from '../config/dbconfig.js';
import useWebSocket from 'react-use-websocket';
import {SendLogData} from "../config/wslog.js";
import ReactGA from "react-ga4";
import IconButton from "@mui/material/IconButton";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";

const Level1MidContent = ({ instruction, detailsOfSelLetter }) => {

  const navigate = useNavigate();
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});
  useEffect(() => {
    ReactGA.send({ hitType: "pageview", page: logconfig.activityUniqueName+"|"+logconfig.activityName+"|level 1",
     title: logconfig.activityUniqueName+"|"+logconfig.activityName+"|level 1" });
  }, []);

  const [open, setOpen] = useState(false);
  const [hintText, setHintText] = useState("");
  const [hintTitle, setHintTitle] = useState("Instuctions");
  var [mainArr, setmainArr] = useState(SecondLevelLetter);
  var [idxLetter, setIdxLetter] = useState(0);
  const [enableHint, setEnableHint] = useState(0);
  const [hintInstr, setHintInstr] = useState({});
  const [openInstrun, setOpenInstrun] = useState(false);
         
  const handleClose = () => {
      setHintText("");
      setOpen(false)
  };
        
  /* const toggleDialog = () => {
    localStorage.setItem('index', idxLetter);
    navigate("/lanchpage/patrimage");
  };  */
  
  const toggleDialog = () => {
    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Instruction button clicked",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Instruction button clicked",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Instruction",
      "Clicked",
      "Click on Instruction Button",
      [],
      [],
      [],
      []
    )

    setOpenInstrun(true);
  };
  
  const handleCloseInstrun = () => {
      setOpenInstrun(false);
  }; 
  
  const handleChange = (e) => {
    
    if(e.target.value=="2")
    {
      ReactGA.event({
        action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Level 2 button clicked",
        category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Level 2 button clicked",
      });
  
      SendLogData(
        sendJsonMessage,
        logconfig.activityName,
        "Level 1",
        "Clicked",
        "Click on Level 1 Button",
        [],
        [],
        [],
        []
      )
      navigate("/l2-select-letter");
    }
  };
  const prevLetter = () => {
    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Previous button clicked",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Previous button clicked",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Previous",
      "Clicked",
      "Click on Previous Button",
      [],
      [],
      [],
      []
    )
      if(idxLetter > 0){
          var inputs = document.getElementsByTagName('select');
          for(var i=0; i<inputs.length; i++ ){
              inputs[i].selectedIndex = 0;
              inputs[i].style.borderColor = "black";
              inputs[i].style.backgroundColor = "#e3e3e3";
          }      
          
          // ==================== //
          setIdxLetter(idxLetter-1); 
          setEnableHint(0) 
      }
  };
  
  const nextLetter = () => {

    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Next button clicked",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Next button clicked",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Next",
      "Clicked",
      "Click on Next Button",
      [],
      [],
      [],
      []
    )
      var lengthLetter = mainArr.length;

      if(idxLetter===4)
        {
          navigate("/completedLevel1");
        }
      
      if(idxLetter < lengthLetter-1) {
          var inputs = document.getElementsByTagName('select');
          for(var i=0; i<inputs.length; i++ ){
              inputs[i].selectedIndex = 0;
              inputs[i].style.borderColor = "black";
              inputs[i].style.backgroundColor = "#e3e3e3";
          }  
          
          // ==================== //    
          setIdxLetter(idxLetter+1); 
          setEnableHint(0) 
      }
      
      if(idxLetter)
      {

      }
  }; 
  
  const checkLetter = () => {

    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Submit button clicked",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1| Submit button clicked",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Submit",
      "Clicked",
      "Click on Submit Button",
      [],
      [],
      [],
      []
    )

      setEnableHint(1);
      const letterDetails = mainArr[idxLetter];     
      const listKeys = Object.keys(letterDetails);
      var objHint = {};
            
      listKeys.map((word, index) => {
            if( Array.isArray(letterDetails[word])){
                if(letterDetails[word].length !== 0){
                    letterDetails[word].map((details, idxDet) => {
                    
                        // Details of the target elements.........
                        var idOfElement = word + "_" + idxDet;  // generate Id string
                        var targetElement = document.getElementById(idOfElement);  // Get element by Id
                        
                        if(details.options !== "" ){
                            if(details.correct === targetElement.selectedOptions[0].innerHTML){
                                 //document.getElementById(idOfElement).style.borderColor = "green";
                                document.getElementById(idOfElement).style.backgroundColor = "#C0F2B4";
                                objHint[idOfElement] = details.feedbackCorrent;
                            }else{
                                //document.getElementById(idOfElement).style.borderColor = "red";
                                document.getElementById(idOfElement).style.backgroundColor = "#F2B4B4";
                                objHint[idOfElement] = details.feedbackIncorrent;
                            }
                        }
                        
                    });                    
                }
            }
      })
           
      setHintInstr(objHint);
  };
  
  const getFeedback = (e) => {
      var idOfElement = e.target.id;
      const myArray = idOfElement.split("_");
      const varId = myArray[0]+"_"+myArray[2];
      
      setHintText(hintInstr[varId]);
      setOpen(true);
  };      
  
  return (
    <div className="" style={{ height: "100%", width:"100%"}}>
      <div
        className="row-md-auto"
        style={{ height: "95%" }}
      >
        <div className="row-md-auto d-flex ">
          <div className="" style={{width:"30%"}}>
            <h6
              className=""
              style={{
                marginTop: "2%",
                marginLeft: "1vh",
                color: "#220730",
              }}
            >
              {/* <strong style={{fontSize:"1.2rem"}}>Level 1</strong> */}
            </h6>
          </div>
          <div className="col text-center">
            <h5 style={{ paddingTop: "10px", color: "#4E0870" }}>
              <strong style={{color:"#412410"}}> {mainArr === null ? <>
            <h1>Content Not available .... !! </h1>
        </> : <> पत्रम् लिखत </> } </strong>
            </h5>
          </div>
                  
          <div className="col-md-auto" style={{display:"flex", width:"30%", justifyContent: "right"}}>
            {/* <button style={{ borderRadius:"5px", height:"90%", marginRight:"2vh"}} className="btnsubmit"
            onClick={toggleDialog}>INSTRUCTIONS</button> */}
            <button onClick={toggleDialog} className="text-center btnall m-1 shadow" style={{color:"#fff",backgroundColor:"#1565c0"}}>
            INSTRUCTIONS
            </button>
            <select class="form-select m-1" aria-label="Default select example" onChange={handleChange}>
              <option disabled>Select the level</option>
              <option value="1" selected disabled>Level 1</option>
              <option value="2" >Level 2</option>
            </select>
                        
           
          </div>
        </div>
        <div
          className="row"
          style={{
            // border: "1px solid #A7A8AB",
            height: "92%",
            width: "100%",
            borderRadius: "8px",
            marginLeft: "0.1%",
            marginRight: "0.1%",
            // backgroundColor: "#E4CDFF",
            paddingLeft: "1%",
            paddingTop: "1%",
            fontSize: "2.2vh",
            border: "1px solid #BAB7BD",
          }}
        >
        
        {mainArr === null ? <>
            <h1>Content Not available .... !! </h1>
        </> : 
        
          <div className="row-md-auto overflow-auto" style={{fontSize: "2.2vh", height:"87%"}}>
            <div className="row d-flex justify-content-center" style={{color:"black"}}> {mainArr[idxLetter].titleOfLetter} </div> 

            {/* ################ Subject == Start : Display the contents of Date ################### */} 

            <div className="row-md-auto wrap">  
                  {Object.keys(mainArr[idxLetter]).map((keyName, index) =>
                      <>
                      {Array.isArray((mainArr[idxLetter])[keyName]) ? 
                          ((mainArr[idxLetter])[keyName]).length !== 0 ?                      
                             <> 
                                 <div id={keyName} style={{maxWidth:"100%", display: "inline", flexWrap: "wrap", margin: "0"}}>
                                     { ((mainArr[idxLetter])[keyName]).map((slotitem, index1) =>
                                        <>
                                             <div id={keyName+"_"+index1+"_"+"2"} style={{display:"flex", marginRight:"0.5%", marginBottom:"0.4%", color:"black"}}>
                                                 {slotitem.options === "" ? <>{slotitem.sentence}</> :
                                                 <>
                                                 
                                                     {keyName === "subject" ? <div >{slotitem.sentence}</div> : <></>}
                                                 
                                                     <select className="letterdropdown"
				                         size="sm"
				                         aria-label="Default select example"
				                         style={{ borderWidth: "0px", fontSize: "2.2vh",
				                             borderRadius: "5px", paddingLeft: "1%",
				                             borderColor: "black", marginRight:"0px",
                                     backgroundColor:"#e3e3e3"
				                         }}
				                         id={keyName+"_"+index1}                                         
                                                     >
                                                         <option disabled hidden selected></option>
                                                         {slotitem.options.map((word, index) => (
                                                             <option id={word} value={word} className="col">{word}</option>
                                                         ))}
                                                         
                                                     </select>
                                                     
                                                     {enableHint === 1 ?  
                                                         <img id={keyName+"_"+"hint_"+index1}
                                                             src={i_image}
                                                             style={{ marginLeft: "1vh",height:"3.5vh",width:"3.5vh",cursor:"pointer" }}
                                                             onClick={getFeedback} alt="i"
                                                         >
                                                         </img>   
                                                         : <></>
                                                     }
                                               </>}
                                          </div>                                              
                                     </>)}
                                 </div>
                                 <p></p>       
                             </>
                              
                          : <></>
                          : <></>
                      }
                  
                      </>                  
                  )}
            </div>
                                    
            {/* ################ Subject == End : Display the contents ################### */}
	    
	      <Dialog
		open={open}
		onClose={handleClose}
		aria-labelledby="alert-dialog-title"
		aria-describedby="alert-dialog-description"
		PaperProps={{ sx: { width: "30%", maxHeight: 300 }}}
	      >
		<DialogTitle style={{minWidth:"50%"}} id="alert-dialog-title"> Feedback </DialogTitle>
		<DialogContent>
		  <DialogContentText id="alert-dialog-description" dangerouslySetInnerHTML={{__html: hintText}}> 
        {/* {hintText}  */}
        </DialogContentText>
		</DialogContent>
		<DialogActions>
		  <Button onClick={handleClose}>Cancel</Button>
		  <Button onClick={handleClose} autoFocus> Ok </Button>
		</DialogActions>
	      </Dialog>        

	      <Dialog
		open={openInstrun}
		onClose={handleCloseInstrun}
		aria-labelledby="alert-dialog-title"
		aria-describedby="alert-dialog-description"
		PaperProps={{ sx: {
		               width: "80%",
		               maxHeight: "56%",
		               }
		           }}
	      >
		<DialogTitle style={{minWidth:"80%"}} id="alert-dialog-title">
		  {hintTitle}
		</DialogTitle>
		<DialogContent dividers style={{marginLeft:"5%"}}>
		  <DialogContentText id="alert-dialog-description">
		    <div style={{ maxHeight: "50vh", padding: "2%" }}>
		        <div>
		            <ol>
		                <li style={{color:"black"}}>The letter displayed, has empty input boxes to be filled.</li>
		                <li style={{color:"black"}}>For each empty input box, select an appropriate option from the dropdown.</li>
		                <li style={{color:"black"}}>Click on the "CHECK" button to verify.</li>
		                <li style={{color:"black"}}>For incorrect answers, click on the "i" icon.</li>
		                <li style={{color:"black"}}>Based on the hints given, try to choose the correct option.</li>
		                <li style={{color:"black"}}>Click on the "CHECK" button to verify again.</li>
		                <li style={{color:"black"}}>Click on the "NEXT" button to attempt the next letter.</li>
		                <li style={{color:"black"}}>Click on the "PREVIOUS" button to go to the previous letter.</li>
		                {/* <li style={{color:"black"}}>Click on "Select Level" to attempt "स्तर 1" or "स्तर 2".</li> */}
		            </ol>
		        </div>
		    </div>
		  </DialogContentText>
		</DialogContent>
		<DialogActions>
      <Button variant="contained" className="bg-primary" size="small" onClick={handleCloseInstrun} autoFocus>Ok</Button>
		  <Button variant="contained" className="bg-danger" size="small" onClick={handleCloseInstrun}>Cancel</Button>
		</DialogActions>
	      </Dialog>
           
          </div> 
          
        }
           <br/>
              <div style={{maxWidth:"100%",  justifyContent:"center", textAlign: "center", margin: "0"}}>                 
                {/* <button style={{minWidth:"10%", margin:"1%"}} onClick={prevLetter} className="btnnextNew"> PREV</button>    */}
                <Tooltip title="Previous Letter" >
                  <IconButton onClick={prevLetter}
                      sx={{
                      marginRight:"100px",
                      backgroundColor: "#F6A700",
                      color: "#412410",
                      width: { xs: "30px", sm: "30px", md: "40px" },
                      height: { xs: "30px", sm: "30px", md: "40px" },
                      "&:hover": { backgroundColor: "#F6A700" },}}>
                      <ArrowBackIcon sx={{ fontSize: { xs: "20px", sm: "30px", md: "35px" } }}/>
                  </IconButton>  
              </Tooltip>
                {/* <button onClick={prevLetter} className="text-center btnall m-1 shado" style={{color:"#fff",backgroundColor:"#f6a700"}}>PREV</button> */}
                {/* <button style={{minWidth:"10%", margin:"1%"}} onClick={checkLetter} className="btnsubmit"> CHECK </button> */}
                <button onClick={checkLetter} className="text-center btnall m-1 shado" style={{color:"#fff",backgroundColor:"#439803"}}>CHECK</button> 
                {/* <button style={{minWidth:"10%", margin:"1%"}} onClick={nextLetter} className="btnnext" > NEXT </button>     */}
                {/* <button onClick={nextLetter} className="text-center btnall m-1 shado" style={{color:"#fff",backgroundColor:"#f6a700"}}>NEXT</button>    */}
              <Tooltip title="Next Letter" >
                  <IconButton onClick={nextLetter}
                      sx={{
                      marginLeft:"100px",
                      backgroundColor: "#F6A700",
                      color: "#412410",
                      width: { xs: "30px", sm: "30px", md: "40px" },
                      height: { xs: "30px", sm: "30px", md: "40px" },
                      "&:hover": { backgroundColor: "#F6A700" },}}>
                      <ArrowForwardIcon sx={{ fontSize: { xs: "20px", sm: "30px", md: "35px" } }}/>
                  </IconButton>  
              </Tooltip>
              </div>         
        </div>                 
        </div>        
      </div>
  );
};

export default Level1MidContent;
