import React, { useState } from "react";
import {useEffect, useRef} from 'react';
import Confetti from "react-confetti";
import { useNavigate } from "react-router-dom";

const CompletedMidContentLevel2 = ({}) => {


  const navigate = useNavigate();

  const onFinish=()=>{
    navigate("/");
  }

  
  return (
    <div>
      <Confetti
        className="canvas"
        numberOfPieces={150}
        gravity={0.15}
      />
      <div className="compeletddiv">
                  <label className="txtcomplete bg-white p-2 shadow rounded-2" style={{marginTop:"15%"}}>Congratulations! You have completed all the letters.</label>
                </div>
                <br/><button  onClick={onFinish} className="btnclear">FINISH</button>
      
    </div>
  );
};

export default CompletedMidContentLevel2;
