import { NmLaunchpage } from "olabsnxtg-sanskrit";
import React,{useState} from "react";
import { useTranslation } from "react-i18next";
import ActStartPopupContent from "../popups/ActStartPopupContent";
import { useEffect } from "react";
import Launcher_icon from "../Img/launcher_icon.png"
import logconfig from '../config/dbconfig.js';
import useWebSocket from 'react-use-websocket';
import {SendLogData} from "../config/wslog.js"

export const Launchpage = () => {



  const { t } = useTranslation();
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});
  const [pageName,setPageName] = useState("LauncherPage");
  var arr = [t("home_2"),t("home_3")];


  
  const L_Start_Btn_Fn = (test) => {
    console.log('I was triggered during componentDidMount '+test);
    SendLogData(
      sendJsonMessage,
      pageName,
      "Start",
      "Clicked",
      "Click on Start Button"
    )
  }

  const L_Okay_Btn_Fn = () => {
    console.log('I was triggered during componentDidMount');
    SendLogData(
      sendJsonMessage,
      pageName,
      "Cancel",
      "Clicked",
      "Click on Cancel Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"What are we going to learn?"}]
    )
  }


  const L_Cancel_Btn_Fn = () => {
    console.log('I was triggered during componentDidMount');
    SendLogData(
      sendJsonMessage,
      pageName,
      "Cancel",
      "Clicked",
      "Click on Cancel Button",
      [],
      [{"popuptype":"Confirmation box","popuptext":"What are we going to learn?"}]
    )
  }

  return (
    <NmLaunchpage
      L_title={t("obj_title")}
      L_objective={t("obj_title")}
      L_act_objective={t("home_1")}
      L_array={arr}
      L_learning_outcome={t("Learn_outcome")}
      L_startbutton={t("Start")}
      L_actstartPopup_content_comp={<ActStartPopupContent />}
      L_actstartPopup_content_title={t("start_heading1")}
      L_ok={t("start_ok")}
      L_cancel={t("start_cancel")}
      L_navigate_to="levels"
      Launcher_icon={Launcher_icon}

      // L_Start_Btn_Fn ={L_Start_Btn_Fn}
      // L_Okay_Btn_Fn ={L_Okay_Btn_Fn}
      // L_Cancel_Btn_Fn ={L_Cancel_Btn_Fn}

      ActivityUniqueName={logconfig.activityUniqueName}
      ActivityName={logconfig.activityName}

      SendLogData={SendLogData}
      sendJsonMessage={sendJsonMessage}

    />
  );
};
