
import React from "react";
import "./Mid.css";
import { useTranslation } from "react-i18next";
import fig1 from "../Img/fig1.png";
import fig2 from "../Img/fig2.png";
import info from "../Img/info.png";

const ProcedureMidContent = () => {
  const { t } = useTranslation();


  return (
    <div className="overflow-auto scrollbar-primary" style={{ height: "95%",marginTop:"15px" }}>
      <div className="my-1 proInstructext" style={{ width: "98%" }}>
        
      <h3 style={{textAlign:'left', color:"#412410"}}><b>{t("procedure_title")}</b></h3>
      <br/>

      <h5 style={{color:"#412410"}}><b>{t("procedure_heading1")}</b></h5><br/>
     
      <h5 style={{color:"#412410"}}><b>{t("procedure_heading2")}</b></h5>
      <h6 style={{color:"#412410"}}><b>{t("procedure_heading3")}</b></h6>

      <ol>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_1")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_2")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_3")}}/><br/>
        <div>
            <div className="row">{/* row start */}
              <div className="text-center">
                <img src={fig1} className="border border-dark img-class"/>
              </div>
            </div>{/* row end */}
            
            <div className="text-center">
              <label className="fw-bold">Fig. 1: Level 1 पत्रम् लिखत</label>
            </div>
          </div>
        </li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_4")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_5")}}/></li>
        {/* <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_6")}}/></li> */}
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_7")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_8")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point_9")}}/></li>
      </ol> 
                
      <br/>


      <h5 style={{color:"#412410"}}><b>{t("procedure_heading22")}</b></h5>
      <h6 style={{color:"#412410"}}><b>{t("procedure_heading3")}</b></h6>

      <ol>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point2_1")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point2_2")}}/><br/>
        <div>
            <div className="row">{/* row start */}
              <div className="text-center">
                <img src={fig2} className="border border-dark img-class"/>
              </div>
            </div>{/* row end */}
            
            <div className="text-center">
              <label className="fw-bold">Fig. 2: Level 2 पत्रम् सम्पूर्णं कुरुत</label>
            </div>
          </div>
        </li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point2_3")}}/>
        </li>
        <li><label/> On the incorrect response, the informative <img src={info}  height={20} style={{marginLeft:"5px",marginRight:"5px"}}/> icon is there. Click on the <img src={info}  height={20} style={{marginLeft:"5px",marginRight:"5px"}}/> icon to check the detailed feedback. </li>
          <li><label dangerouslySetInnerHTML={{__html: t("procedure_point2_42")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point2_5")}}/></li>
        <li><div dangerouslySetInnerHTML={{__html: t("procedure_point2_6")}}/></li>
      </ol> 

      <h6 style={{color:"#412410"}}><b>{t("procedure_point2_7")}</b></h6>
      </div>
    </div>
  );
};

export default ProcedureMidContent;
