
import React,{useEffect} from "react";
// import { useNavigate } from "react-router-dom";
// import BackNextBar from "../MajorComponents/BackNextBar";
import "./Mid.css";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
// import play from "../Img/play.png"
import play from "../Img/playicon.png";
import level_1 from "../Img/level_1.png";
import level_2 from "../Img/level_2.png";
import "../css/midquery.css";
import logconfig from '../config/dbconfig.js';
import useWebSocket from 'react-use-websocket';
import {SendLogData} from "../config/wslog.js";
import ReactGA from "react-ga4";



const LevelsMidContent = () => {
  const { t } = useTranslation();

  const navigate = useNavigate();
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});

  useEffect(() => {
    ReactGA.send({ hitType: "pageview", page: logconfig.activityUniqueName+"|"+logconfig.activityName+"|levels",
     title: logconfig.activityUniqueName+"|"+logconfig.activityName+"|levels" });
  }, []);

  const onLeve1=()=> {

    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1 button",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 1 button",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Level 1",
      "Clicked",
      "Click on Level 1 Button",
      [],
      [],
      [],
      []
    )

    navigate("/level1");
  }
  const onLeve2=()=> {

    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 2 button",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 2 button",
    });


    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Level 2",
      "Clicked",
      "Click on Level 2 Button",
      [],
      [],
      [],
      []
    )
    
    navigate("/l2-select-letter");
  }


  return (
    <div className="d-flex align-items-center justify-content-center" style={{height: "98%"}} >
    <div className="m-md-5  m-2 p-md-5 p-3  levelbox text-black shadow rounded-2">
   <div>
       {/* <h4 className="p-3" style={{fontWeight:"normal"}}> Level 1</h4> */}
       <img  src={level_1}  className="level-image-size"/><br/>
       <label className="level_title m-1" style={{color:"#412410"}}>पत्रम् लिखत</label><br/>
       <button className="border-0 shadow rounded p-2 text-white let_go_btn" style={{backgroundColor:"#0e4fa9"}} onClick={onLeve1}>LET'S GO</button>
     </div>
   </div>
   <div className="m-md-4 m-1 p-lg-4 p-1"></div>
   <div className="m-md-5 m-2 p-md-5 p-3  levelbox text-black shadow rounded-2" style={{cursor:"pointer"}} >
   <div>
       {/* <h4 className="p-3" style={{fontWeight:"normal"}}> Level 2</h4> */}
       <img  src={level_2}  className="level-image-size"/><br/>
       <label className="level_title m-1" style={{color:"#412410"}}>पत्रम् सम्पूर्णं कुरुत</label><br/>
       <button className="border-0 shadow rounded p-2 text-white let_go_btn" style={{backgroundColor:"#0e4fa9"}} onClick={onLeve2}>LET'S GO</button>
     </div>
   </div>
   </div>

  );
};

export default LevelsMidContent;
