
import React,{useState,useEffect} from "react";
import "./Mid.css";
import { useTranslation } from "react-i18next";
import { useNavigate } from "react-router-dom";
import ListOfLetters from "../resources/FirstLevelLetter.json";
import {SendLogData} from "../config/wslog.js";
import ReactGA from "react-ga4";
import logconfig from '../config/dbconfig.js';
import useWebSocket from 'react-use-websocket';

const   L1SelecctLetterMidContent = () => {
  const { t } = useTranslation();
  const {sendJsonMessage } = useWebSocket(logconfig.logurl, {share: true,});

  const navigate = useNavigate();

  const onLeve1=()=> {
    navigate("/l2-select-letter");
  }
  const onLeve2=()=> {
    navigate("/level2");
  }

  useEffect(() => {
    ReactGA.send({ hitType: "pageview", page: logconfig.activityUniqueName+"|"+logconfig.activityName+"|level 2",
     title: logconfig.activityUniqueName+"|"+logconfig.activityName+"|level 2" });
  }, []);

  const [open, setOpen] = useState(false);


  const handleRedirect = () => {
    //alert("handle");
        
    var idSelected = document.getElementById("selectLetter").selectedOptions[0].value;
    var textHtml = document.getElementById("selectLetter").selectedOptions[0].value;
    var letterContent = {};
          
    if(idSelected === "-1"){
        setOpen(true);
        alert("Please Select Letter")
        return ;
    }
    
    ListOfLetters.map((slotitem, idx) => {          
        if(slotitem.id == parseInt(idSelected)){
            letterContent = slotitem;
        }          
    })

    ReactGA.event({
      action: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 2| Submit button clicked",
      category: logconfig.activityUniqueName+"|"+logconfig.activityName+"|Level 2| Submit button clicked",
    });

    SendLogData(
      sendJsonMessage,
      logconfig.activityName,
      "Submit",
      "Clicked",
      "Click on Submit Button",
      [],
      [],
      [],
      []
    )
          
    // navigate to ll5 with  props --- 
    navigate("/level2", {state: {
            id: parseInt(idSelected),
            letterObject: letterContent,
        },
    });            
}


  return (
    <div className="overflow-auto scrollbar-primary" style={{ height: "95%",marginTop:"15px" }}>
      <div className="my-1" style={{ width: "98%" }}>


            <div className="row">
                <div className="col-0 col-md-1 col-lg-2"></div>
                <div className="col-12 col-md-10 col-lg-8 bg-white shadow rounded-2 i_t p-1">
                  <div className="row">
                    <div className="col-4 col-md-2 text-start">Instruction:</div>
                    <div className="col-8 col-md-10 text-start">{t("instruction_title1")}</div>
                  </div>
                  <div className="row">
                    <div className="col-4 col-md-2 text-start"></div>
                    <div className="col-8 col-md-10 text-start">{t("instruction_title2")}</div>
                  </div>
                </div>
                <div className="col-0  col-md-1  col-lg-2"></div> 
            </div>


            <div className="row text-center mt-5">
              <div className="col-0 col-md-2 col-lg-3"></div>
              <div className="col-12  col-md-8  col-lg-6">
                  <select name="selectLetter"  id="selectLetter" className="letterdropdown1">
                    <option value="-1">{t("dropdown")}</option>
                    {ListOfLetters.map((slotitem, idx) => 
                                    <option key={slotitem.id} value={slotitem.id}> {slotitem.titleOfLetter} </option>
                                    )}
                  </select>
              </div>
              <div className="col-0  col-md-2  col-lg-3"></div>
            </div>

                <br/><br/><br/>
                <button onClick={handleRedirect} className="text-center btnall m-1 shadow" style={{color:"#fff",backgroundColor:"#439803"}}>
                      {t("submit")}</button>





      </div>
   </div>
  );
};

export default L1SelecctLetterMidContent;
